// ============================================================
// Arma un aviso legible a partir del error que mando n8n.
// No asume que todos los campos vengan siempre presentes.
// ============================================================

const d = $input.first().json;

// Todo lo que viene del error se escapa antes de ir al HTML del mail: el
// mensaje puede traer texto que mando un visitante (por ejemplo, lo que
// escribio en un formulario) y no tiene que poder meter HTML en el aviso.
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const workflowNombre = d.workflow?.name || 'workflow desconocido';
const mensaje = d.execution?.error?.message || d.execution?.lastNodeExecuted || 'sin mensaje de error';
const nodo = d.execution?.lastNodeExecuted || 'sin dato';
const urlCruda = String(d.execution?.url || '');
const url = urlCruda.startsWith('https://') ? urlCruda : '';
const fecha = new Date().toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' });

const asunto = `⚠️ Obol: fallo en "${workflowNombre}"`.slice(0, 150);
const cuerpo = `
<div style="font-family:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;max-width:520px;margin:0 auto;color:#12212E;line-height:1.6">
  <p style="font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:#c0392b;margin:0 0 14px">Obol Finance · Alerta</p>
  <h1 style="font-family:Georgia,serif;font-size:22px;font-weight:600;margin:0 0 16px">Se rompió algo en "${esc(workflowNombre)}"</h1>
  <p style="margin:0 0 8px"><strong>Nodo:</strong> ${esc(nodo)}</p>
  <p style="margin:0 0 8px"><strong>Mensaje:</strong> ${esc(mensaje)}</p>
  <p style="margin:0 0 16px"><strong>Cuándo:</strong> ${esc(fecha)}</p>
  ${url ? `<p style="margin:0 0 16px"><a href="${esc(url)}" style="color:#c0392b">Ver la ejecución en n8n →</a></p>` : ''}
  <hr style="border:none;border-top:1px solid #E5E0D6;margin:0 0 14px">
  <p style="font-size:12px;color:#8a8378;margin:0">Este aviso sale solo cuando un nodo tira un error real (por ejemplo, una credencial vencida o una API que devuelve algo inesperado). Los fallos ya previstos en el codigo (API externa caida, mail invalido, etc.) no generan este aviso porque el workflow los maneja solo.</p>
</div>`;

return [{ json: { asunto, cuerpo } }];
